// Only complete names generated by Rest Guard are eligible. Never use a broad
// prefix match: unrelated manual/auto/quick/cloud/configuration saves stay put.
const REST_NAME = /^RestGuard_(Idle|Time|Turn|Night)_T\d+_(\d{8}-\d{6}-\d{3})_\d+-[a-z0-9]{1,6}(?:\.Civ7Save)?$/i;
const baseName = name => name.replace(/\.Civ7Save$/i, '');

export function oldRestSaves(files, keep, scope, protectedName) {
  if (!Array.isArray(files) || !Number.isInteger(keep) || keep < 1) return [];
  const unique = new Map();
  for (const file of files) {
    if (typeof file?.fileName !== 'string' || !REST_NAME.test(file.fileName) ||
        file.location !== scope.location || file.locationCategories !== scope.category ||
        file.type !== scope.type || file.contentType !== scope.contentType || file.isAutosave || file.isQuicksave) continue;
    unique.set(file.fileName, file);
  }
  const saves = [...unique.values()].sort((a, b) => {
    const at = Number(a.saveTime), bt = Number(b.saveTime);
    if (Number.isFinite(at) && Number.isFinite(bt) && at !== bt) return bt - at;
    return b.fileName.match(REST_NAME)[2].localeCompare(a.fileName.match(REST_NAME)[2]) || b.fileName.localeCompare(a.fileName);
  });
  // A stale/partial query must never prune before seeing the newly saved file.
  const latest = saves.find(file => baseName(file.fileName) === protectedName);
  if (protectedName && !latest) return [];
  const ordered = latest ? [latest, ...saves.filter(file => file !== latest)] : saves;
  return ordered.slice(keep);
}

export class RestRetention {
  constructor(env) { this.env = env; this.job = null; this.pending = null; this.disposed = false; }

  request(state) {
    if (this.disposed || state?.status !== 'saved') return;
    state.cleanup = 'pending';
    this.pending = state;
  }

  poll() {
    if (this.disposed) return;
    if (this.job && this.env.now() >= this.job.deadline) return this.finish('failed');
    if (this.env.busy()) return;
    if (!this.job && this.pending) {
      const state = this.pending;
      this.pending = null;
      const job = this.job = { state, scope: this.env.scope(), phase: 'query', id: null,
        files: [], deleting: null, deadline: this.env.now() + 30000 };
      try {
        job.id = this.env.query(job.scope);
        if (job.id === undefined || job.id === null || job.id < 0) this.finish('failed');
      } catch (_) { this.finish('failed'); }
      return;
    }
    const job = this.job;
    if (!job || job.phase !== 'ready') return;
    const old = oldRestSaves(job.files, this.env.keep(), job.scope, job.state.fileName);
    if (!old.length) return this.finish('done');
    // Send one native removal at a time, preserving all identity fields returned
    // by the query; never derive a filesystem path or guess another save slot.
    job.deleting = old[old.length - 1];
    job.phase = 'delete';
    job.deadline = this.env.now() + 30000;
    try { if (!this.env.remove(job.deleting) && this.job === job) this.finish('failed'); }
    catch (_) { this.finish('failed'); }
  }

  onFiles(id, files) {
    const job = this.job;
    if (!job || job.phase !== 'query' || id !== job.id) return;
    try { this.env.close(job.id); job.id = null; }
    catch (_) { return this.finish('failed'); }
    if (!Array.isArray(files) || !files.some(file => typeof file?.fileName === 'string' &&
        baseName(file.fileName) === job.state.fileName)) return this.finish('failed');
    job.files = files;
    job.phase = 'ready';
  }

  onRemoved(result) {
    const job = this.job;
    if (!job || job.phase !== 'delete' || this.env.isPending(result)) return;
    if (result?.fileName !== undefined && result.fileName !== job.deleting.fileName) return;
    if (!this.env.succeeded(result)) return this.finish('failed');
    job.files = job.files.filter(file => file.fileName !== job.deleting.fileName);
    job.deleting = null;
    job.phase = 'ready';
  }

  finish(status) {
    const job = this.job;
    this.job = null;
    if (!job) return;
    if (job.id !== null) { try { this.env.close(job.id); } catch (_) {} }
    job.state.cleanup = status;
    if (status === 'failed') this.env.warn?.();
  }

  cancel() { this.pending = null; this.finish('failed'); }
  dispose() { this.disposed = true; this.cancel(); }
}

export function createRestRetention(keep, busy) {
  const retention = new RestRetention({
    now: () => Date.now(), keep, busy,
    scope: () => ({ location: SaveLocations.LOCAL_STORAGE, category: SaveLocationCategories.NORMAL,
      type: GameStateStorage.getGameConfigurationSaveType(), contentType: SaveFileTypes.GAME_STATE }),
    query: scope => GameStateStorage.querySaveGameList({ Location: scope.location, Type: scope.type,
      LocationOptions: scope.category, ContentType: scope.contentType, ForceRefresh: true }),
    close: id => GameStateStorage.closeFileListQuery(id),
    remove: file => Network.deleteGame({ Location: file.location, LocationCategories: file.locationCategories,
      Type: file.type, ContentType: file.contentType, FileName: file.fileName, DisplayName: file.displayName,
      Slot: file.slot, AdditionalInfo: file.additionalInfo }),
    isPending: result => result?.result === SerializerResult.RESULT_PENDING,
    succeeded: result => result?.result === SerializerResult.RESULT_OK,
    warn: () => console.warn('[Rest Guard] Rest save retention incomplete; newer and unrelated saves preserved.'),
  });
  const files = (id, list) => retention.onFiles(id, list);
  const removed = result => retention.onRemoved(result);
  const cancel = () => retention.cancel();
  engine.on('FileListQueryResults', files);
  engine.on('RemoveComplete', removed);
  engine.on('LoadComplete', cancel);
  engine.on('LocalPlayerChanged', cancel);
  retention.destroy = () => {
    retention.dispose();
    engine.off('FileListQueryResults', files);
    engine.off('RemoveComplete', removed);
    engine.off('LoadComplete', cancel);
    engine.off('LocalPlayerChanged', cancel);
  };
  return retention;
}
